window.kbPageData["views/entry/k-f6d54a7da76261c3"] = {"key":"entry/k-f6d54a7da76261c3","state":{"route":"entry/k-f6d54a7da76261c3"},"node":{"id":"k-f6d54a7da76261c3","mode":"k","title":"安全生产治本攻坚三年行动","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2024,"title":"安全生产治本攻坚三年行动","slug":"c3df4c4a02fe"}],"directorySummary":"2.安全生产治本攻坚三年行动\n通过三年治本攻坚，地方党委和政府、部门和生产经营单位统筹发展和安全的理念进一\n步强化，坚守安全红线的意识更加强烈，消减重大安全风险、消除重大事故隐患的积极性主\n动性显著增强；重点行业领域建立健全“一件事”由牵头部门组织推动、各相关部门齐抓共\n管，全链条排查整治重大事故隐…","sources":[{"id":"fd834d0f3b0b3f1e","label":"安全生产治本攻坚三年行动","topic":"年度政府工作","category":"时政","text":"2.安全生产治本攻坚三年行动\n通过三年治本攻坚，地方党委和政府、部门和生产经营单位统筹发展和安全的理念进一\n步强化，坚守安全红线的意识更加强烈，消减重大安全风险、消除重大事故隐患的积极性主\n动性显著增强；重点行业领域建立健全“一件事”由牵头部门组织推动、各相关部门齐抓共\n管，全链条排查整治重大事故隐患的责任体系，安全监管能力显著提升；2024 年底前基本\n消除 2023 年及以前排查发现的重大事故隐患存量，2025 年底前有效遏制重大事故隐患增量，\n2026 年底前形成重大事故隐患动态清零的常态化机制；针对重大安全风险的一批“人防、\n技防、工程防、管理防”措施落地见效，本质安全水平大幅提升；全国安全生产形势持续稳\n定向好，重特大生产安全事故多发势头得到有效遏制。\n——《安全生产治本攻坚三年行动方案 2024-2026 年》","source":{"doc":"6cbfb01fe723bba64b75","first":50,"last":50,"page":50,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-f6d54a7da76261c3":[]}};
